import threading
import time
from typing import List, Optional
from contextlib import contextmanager

class DatabaseConnection:
    def __init__(self, connection_id: int):
        self.connection_id = connection_id
        self.is_closed = False
        self._event_listeners = []

    def add_event_listener(self, listener):
        if not self.is_closed:
            self._event_listeners.append(listener)

    def remove_event_listener(self, listener):
        if listener in self._event_listeners:
            self._event_listeners.remove(listener)

    def close(self):
        self.is_closed = True
        # Clear all event listeners to prevent memory leaks
        self._event_listeners.clear()

    def __del__(self):
        # Cleanup event listeners on garbage collection
        if hasattr(self, '_event_listeners'):
            self._event_listeners.clear()

class ConnectionPool:
    def __init__(self, min_connections: int = 2, max_connections: int = 10):
        self.min_connections = min_connections
        self.max_connections = max_connections
        self.connections: List[DatabaseConnection] = []
        self._available_connections: List[DatabaseConnection] = []
        self._lock = threading.Lock()
        self._pool_lock = threading.Lock()
        self._closed = False

        # Initialize minimum connections
        for i in range(min_connections):
            conn = DatabaseConnection(i + 1)
            self.connections.append(conn)
            self._available_connections.append(conn)

    def acquire(self) -> DatabaseConnection:
        with self._lock:
            if self._closed:
                raise Exception("Connection pool is closed")

            # Try to get an available connection
            if self._available_connections:
                conn = self._available_connections.pop()
                return conn

            # If we haven't reached max connections, create a new one
            if len(self.connections) < self.max_connections:
                conn = DatabaseConnection(len(self.connections) + 1)
                self.connections.append(conn)
                return conn

            # Wait for a connection to become available
            # In a real implementation, this would use a condition variable
            # For simplicity, we'll just wait and check again
            time.sleep(0.01)
            return self.acquire()

    def release(self, connection: DatabaseConnection):
        with self._lock:
            if self._closed or connection.is_closed:
                return

            # Remove any event listeners that might cause memory leaks
            connection._event_listeners.clear()

            # Return connection to pool if it's still valid
            if connection in self.connections and connection not in self._available_connections:
                self._available_connections.append(connection)

    def close(self):
        with self._lock:
            if self._closed:
                return

            self._closed = True

            # Close all connections and clear references
            for conn in self.connections:
                conn.close()
                # Explicitly clear any remaining references
                conn._event_listeners.clear()

            # Clear all connection references
            self.connections.clear()
            self._available_connections.clear()

    @contextmanager
    def get_connection(self):
        """Context manager for acquiring and releasing connections"""
        conn = None
        try:
            conn = self.acquire()
            yield conn
        finally:
            if conn:
                self.release(conn)

    def get_status(self):
        """Get current pool status for debugging"""
        with self._lock:
            return {
                "total_connections": len(self.connections),
                "available_connections": len(self._available_connections),
                "closed": self._closed
            }
