import ast
import re
from typing import Dict, List

def analyze_code_security(source_code: str) -> dict:
    """
    Analyze Python source code for unsafe pickle deserialization and hardcoded secrets.

    Args:
        source_code (str): The Python source code to analyze

    Returns:
        dict: Analysis results with findings
    """

    findings = {
        "unsafe_pickle_deserialization": [],
        "hardcoded_secrets": []
    }

    try:
        tree = ast.parse(source_code)
    except SyntaxError:
        return findings  # Return empty findings if syntax is invalid

    # Check for unsafe pickle usage
    pickle_patterns = [
        r"pickle\.loads?\(",
        r"pickle\.load\(",
        r"pickle\.Unpickler"
    ]

    # Look for hardcoded secrets using common patterns
    secret_patterns = [
        r'["\'](?:password|secret|token|key|pass|pwd)["\']\s*[=:]\s*["\'][^"\']*["\']',
        r'["\'](?:API|APP|CLIENT)_KEY["\']\s*[=:]\s*["\'][^"\']*["\']',
        r'["\'](?:DATABASE|DB)_PASSWORD["\']\s*[=:]\s*["\'][^"\']*["\']',
        r'["\'](?:JWT|AUTH|SESSION)_SECRET["\']\s*[=:]\s*["\'][^"\']*["\']'
    ]

    # Find unsafe pickle usage
    lines = source_code.split('\n')
    for i, line in enumerate(lines, 1):
        for pattern in pickle_patterns:
            if re.search(pattern, line):
                findings["unsafe_pickle_deserialization"].append({
                    "line_number": i,
                    "line_content": line.strip(),
                    "type": "unsafe_pickle_usage"
                })

    # Find hardcoded secrets
    for i, line in enumerate(lines, 1):
        for pattern in secret_patterns:
            if re.search(pattern, line, re.IGNORECASE):
                findings["hardcoded_secrets"].append({
                    "line_number": i,
                    "line_content": line.strip(),
                    "type": "hardcoded_secret"
                })

    # Additional AST-based checks for more precise detection
    class PickleVisitor(ast.NodeVisitor):
        def __init__(self):
            self.pickle_calls = []

        def visit_Call(self, node):
            if isinstance(node.func, ast.Attribute):
                if (isinstance(node.func.value, ast.Name) and 
                    node.func.value.id == 'pickle' and 
                    node.func.attr in ['loads', 'load']):
                    self.pickle_calls.append({
                        "line_number": node.lineno,
                        "function": node.func.attr
                    })
            self.generic_visit(node)

    class SecretVisitor(ast.NodeVisitor):
        def __init__(self):
            self.secrets = []

        def visit_Assign(self, node):
            for target in node.targets:
                if isinstance(target, ast.Name):
                    if isinstance(node.value, ast.Constant) and isinstance(target.id, str):
                        var_name = target.id.lower()
                        if any(secret_key in var_name for secret_key in ['password', 'secret', 'token', 'key']):
                            self.secrets.append({
                                "line_number": node.lineno,
                                "variable": target.id
                            })
            self.generic_visit(node)

    # Run AST visitors
    pickle_visitor = PickleVisitor()
    pickle_visitor.visit(tree)

    secret_visitor = SecretVisitor()
    secret_visitor.visit(tree)

    # Add AST-based findings
    for call in pickle_visitor.pickle_calls:
        findings["unsafe_pickle_deserialization"].append({
            "line_number": call["line_number"],
            "type": "unsafe_pickle_usage",
            "function": call["function"]
        })

    for secret in secret_visitor.secrets:
        findings["hardcoded_secrets"].append({
            "line_number": secret["line_number"],
            "type": "hardcoded_secret",
            "variable": secret["variable"]
        })

    return findings
