from abc import ABC, abstractmethod
from typing import Dict, Any, List
import logging

# Base classes for the migration components
class MigrationStep(ABC):
    @abstractmethod
    def execute(self) -> bool:
        pass

class DatabaseMigration(MigrationStep):
    def __init__(self, table_name: str, alterations: List[Dict[str, Any]]):
        self.table_name = table_name
        self.alterations = alterations

    def execute(self) -> bool:
        # Simulate database schema alteration
        print(f"Executing database migration on table '{self.table_name}'")
        for alteration in self.alterations:
            print(f"  - {alteration}")
        return True

class ORMMigration(MigrationStep):
    def __init__(self, entity_name: str, updates: Dict[str, Any]):
        self.entity_name = entity_name
        self.updates = updates

    def execute(self) -> bool:
        # Simulate ORM entity update
        print(f"Updating ORM entity '{self.entity_name}'")
        for key, value in self.updates.items():
            print(f"  - {key}: {value}")
        return True

class ControllerMigration(MigrationStep):
    def __init__(self, controller_name: str, endpoint_updates: List[Dict[str, Any]]):
        self.controller_name = controller_name
        self.endpoint_updates = endpoint_updates

    def execute(self) -> bool:
        # Simulate REST controller adaptation
        print(f"Adapting REST controller '{self.controller_name}'")
        for update in self.endpoint_updates:
            print(f"  - Endpoint: {update}")
        return True

class MigrationController:
    """
    Manages a 3-stage migration process:
    1. Database schema alteration
    2. ORM entity update
    3. REST controller adaptation
    """

    def __init__(self):
        self.steps = []
        self.logger = logging.getLogger(__name__)

    def add_database_migration(self, table_name: str, alterations: List[Dict[str, Any]]):
        """Add database schema migration step"""
        migration = DatabaseMigration(table_name, alterations)
        self.steps.append(migration)
        return self

    def add_orm_migration(self, entity_name: str, updates: Dict[str, Any]):
        """Add ORM entity update step"""
        migration = ORMMigration(entity_name, updates)
        self.steps.append(migration)
        return self

    def add_controller_migration(self, controller_name: str, endpoint_updates: List[Dict[str, Any]]):
        """Add REST controller adaptation step"""
        migration = ControllerMigration(controller_name, endpoint_updates)
        self.steps.append(migration)
        return self

    def execute_all(self) -> bool:
        """Execute all migration steps in order"""
        self.logger.info("Starting 3-stage migration process")

        success = True
        for i, step in enumerate(self.steps, 1):
            try:
                self.logger.info(f"Executing migration step {i}")
                if not step.execute():
                    self.logger.error(f"Migration step {i} failed")
                    success = False
                    break
                self.logger.info(f"Migration step {i} completed successfully")
            except Exception as e:
                self.logger.error(f"Migration step {i} failed with error: {str(e)}")
                success = False
                break

        if success:
            self.logger.info("All migration steps completed successfully")
        else:
            self.logger.error("Migration process encountered errors")

        return success

    def get_status(self) -> Dict[str, Any]:
        """Get current migration status"""
        return {
            "total_steps": len(self.steps),
            "completed_steps": len([s for s in self.steps if hasattr(s, 'execute')]),
            "steps": [
                {
                    "type": step.__class__.__name__,
                    "description": str(step)
                } for step in self.steps
            ]
        }

# Example usage:
if __name__ == "__main__":
    # Configure logging
    logging.basicConfig(level=logging.INFO)

    # Create migration controller instance
    migration_controller = MigrationController()

    # Add migration steps
    migration_controller \
        .add_database_migration(
            "users", 
            [
                {"action": "add_column", "column": "email", "type": "VARCHAR(255)"},
                {"action": "modify_column", "column": "name", "type": "VARCHAR(100)"}
            ]
        ) \
        .add_orm_migration(
            "User",
            {
                "add_field": "email",
                "update_field": "name",
                "remove_field": "old_field"
            }
        ) \
        .add_controller_migration(
            "UserController",
            [
                {"endpoint": "/users/{id}/profile", "method": "GET", "new_param": "include_email"},
                {"endpoint": "/users", "method": "POST", "validation": "email_required"}
            ]
        )

    # Execute migrations
    result = migration_controller.execute_all()
    print(f"Migration result: {'SUCCESS' if result else 'FAILED'}")

    # Check status
    status = migration_controller.get_status()
    print(f"Migration Status: {status}")
